const b = $input.first().json.body || {};
const text = String(b.message || '').toLowerCase();
const name = String(b.name || '').trim();
const phone = String(b.phone || '').replace(/[^0-9+]/g, '');
const email = String(b.email || '').trim();
const channel = String(b.channel || 'website');

// what service are they after
// urgency is checked FIRST — a painful case must never be filed as routine
const URGENT = ['emergency','urgent','asap','right now','severe','badly','can\'t sleep','swollen','bleeding','today'];
const SERVICES = {
  'check-up':     ['check up','checkup','control','routine','cleaning','hygiene'],
  'consultation': ['consult','advice','discuss','talk about','quote','estimate'],
  'repair':       ['repair','fix','broken','pain','hurts','problem','not working']
};
let service = 'general appointment';
if (URGENT.some(w => text.includes(w))) {
  service = 'emergency';
} else {
  for (const [k, words] of Object.entries(SERVICES)) {
    if (words.some(w => text.includes(w))) { service = k; break; }
  }
}

// when do they want it
const DAYS = ['monday','tuesday','wednesday','thursday','friday','saturday','sunday'];
let preferred = null;
for (const d of DAYS) if (text.includes(d)) preferred = d;
if (text.includes('tomorrow')) preferred = 'tomorrow';
if (text.includes('today') || service === 'emergency') preferred = 'today';
if (text.includes('next week')) preferred = 'next week';

const morning = /morning|before noon|am\b/.test(text);
const evening = /evening|after work|late|pm\b/.test(text);
const part = morning ? 'morning' : (evening ? 'afternoon' : 'any');

return [{ json: {
  name, phone, email, channel, message: String(b.message || ''),
  service, preferred: preferred || 'any day', part,
  urgent: service === 'emergency',
  has_phone: phone.length >= 7,
  has_email: email.includes('@')
} }];

// Real availability from the node before this one; the enquiry from two nodes back.
const cal = $input.first().json;
const rawBusy = cal.busy
  || (cal.calendars && Object.values(cal.calendars)[0] && Object.values(cal.calendars)[0].busy)
  || [];
const busy = rawBusy.map(b => ({ s: new Date(b.start).getTime(), e: new Date(b.end).getTime() }));
const d = $('Understand the request').first().json;

const S = $('Your settings').first().json;
const DURATION_MIN = S.appointment_minutes || 45;
const OPEN_HOUR = S.open_hour || 9, CLOSE_HOUR = S.close_hour || 18;
const pad = x => String(x).padStart(2, '0');

// candidate hours, in the order this customer would want them
let hours;
if (d.service === 'emergency')      hours = [/*soonest first*/];
else if (d.part === 'morning')      hours = [9, 10, 11];
else if (d.part === 'afternoon')    hours = [15, 16, 17];
else                                hours = [11, 15, 10, 16];

const now = new Date();
const free = [];
for (let day = 0; day <= 6 && free.length < 3; day++) {
  const date = new Date(now); date.setDate(date.getDate() + day);
  if (date.getDay() === 0) continue;   // closed Sundays — remove if you are not
  const todaysHours = d.service === 'emergency'
    ? Array.from({length: CLOSE_HOUR - OPEN_HOUR}, (_, i) => OPEN_HOUR + i)
    : hours;
  for (const h of todaysHours) {
    const start = new Date(date); start.setHours(h, 0, 0, 0);
    if (start.getTime() < now.getTime() + 90 * 60000) continue;   // nothing sooner than 90 min away
    const end = start.getTime() + DURATION_MIN * 60000;
    const clash = busy.some(b => start.getTime() < b.e && end > b.s);
    if (!clash) { free.push(start); if (free.length === 3) break; }
  }
}

const fmt = dt => `${dt.getFullYear()}-${pad(dt.getMonth()+1)}-${pad(dt.getDate())} ${pad(dt.getHours())}:${pad(dt.getMinutes())}`;
const first = d.name.split(' ')[0] || 'there';
const art = /^[aeiou]/i.test(d.service) ? 'an' : 'a';

let reply;
if (free.length === 0) {
  reply = `Hi ${first}, thanks for getting in touch about ${art} ${d.service}. The diary is full this week — we'll come back to you with a time today.`;
} else {
  reply = `Hi ${first}, thanks for getting in touch about ${art} ${d.service}.\n\nI can offer you:\n` +
    free.map((s, i) => `  ${i + 1}) ${fmt(s)}`).join('\n') +
    `\n\nJust reply with 1, 2 or 3 and I'll lock it in.` +
    (d.has_phone ? '' : `\n\nCould you also send a phone number, in case we need to reach you?`);
}

const alert_to_owner = `URGENT: ${d.name || 'Someone'} (${d.phone || 'no phone yet'}) wrote: "${(d.message || '').slice(0, 120)}". First free slot: ${free[0] ? fmt(free[0]) : 'none this week'}.`;

return [{ json: {
  urgent: d.urgent, alert_to_owner,
  status: free.length ? 'slots offered' : 'diary full',
  customer: d.name, phone: d.phone, email: d.email,
  service: d.service, wanted: d.preferred + ' / ' + d.part,
  slots_offered: free.map(s => s.toISOString()),
  slots_readable: free.map(fmt),
  reply_to_customer: reply,
  chat_id: S.telegram_chat_id
} }];

// The page posts back either the chosen slot, or a 1/2/3 choice plus the offered list.
const b = $input.first().json.body || {};
const slots = Array.isArray(b.slots) ? b.slots : String(b.slots || '').split(',').map(s => s.trim()).filter(Boolean);
const choice = parseInt(b.choice, 10);
const start = String(b.slot_start || (choice >= 1 && slots[choice - 1]) || '').trim();
if (!start || isNaN(new Date(start).getTime())) {
  throw new Error('No usable slot: send slot_start as an ISO date, or choice 1-3 together with the offered slots.');
}

const S = $('Your settings (booking side)').first().json;
const DURATION_MIN = S.appointment_minutes || 45;
const startDt = new Date(start);
const endDt = new Date(startDt.getTime() + DURATION_MIN * 60000);

const name = String(b.name || 'Customer').trim();
const phone = String(b.phone || '').trim();
const email = String(b.email || '').trim();
const service = String(b.service || 'appointment').trim();

const pad = x => String(x).padStart(2, '0');
const nice = `${startDt.getFullYear()}-${pad(startDt.getMonth()+1)}-${pad(startDt.getDate())} ${pad(startDt.getHours())}:${pad(startDt.getMinutes())}`;
const first = name.split(' ')[0] || 'there';

// reminder lands 24 h before the visit — or in 5 minutes if the visit is sooner than that
const remindAt = new Date(Math.max(Date.now() + 5 * 60000, startDt.getTime() - 24 * 3600000));

return [{ json: {
  slot_start: startDt.toISOString(),
  slot_end: endDt.toISOString(),
  summary: `${service} — ${name}`,
  event_notes: `Booked by the website workflow.\nPhone: ${phone || 'not given'}\nEmail: ${email || 'not given'}\nOriginal message: ${String(b.message || '').slice(0, 300)}`,
  name, phone, email, service,
  slot_readable: nice,
  reply_to_customer: `Locked in, ${first} — ${nice}. You'll get a reminder the day before. If something comes up, just write to us on the same page.`,
  owner_note: `BOOKED: ${name} (${phone || 'no phone'}) — ${service}, ${nice}.`,
  reminder_email_subject: `Reminder: your ${service} tomorrow`,
  reminder_email_text: `Hi ${first},\n\nA quick reminder about your ${service} on ${nice}.\n\nIf something has come up, reply to this email or write to us on the website and we'll find you another time.\n\nSee you then.`,
  owner_reminder_fallback: `REMINDER DUE, no email on file: call ${name} (${phone || 'no phone'}) about the ${service} on ${nice}.`,
  remind_at: remindAt.toISOString(),
  has_email: email.includes('@'),
  chat_id: S.telegram_chat_id
} }];
